CREATE TABLE invitations(id TEXT PRIMARY KEY,code_hash TEXT NOT NULL UNIQUE,code_prefix TEXT NOT NULL,created_by TEXT REFERENCES users(id),note TEXT NOT NULL DEFAULT '',max_uses INTEGER NOT NULL DEFAULT 1 CHECK(max_uses BETWEEN 1 AND 100),used_count INTEGER NOT NULL DEFAULT 0 CHECK(used_count>=0 AND used_count<=max_uses),expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE invitation_redemptions(invitation_id TEXT NOT NULL REFERENCES invitations(id),user_id TEXT NOT NULL UNIQUE REFERENCES users(id),redeemed_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(invitation_id,user_id));
